contracts/Common/Definitions.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;


// ━━━━  EXTERNAL AUTHORITIES  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

// The canonical SafeSwap protocol config signer. Every contract reads its ChainConfig entries from this address's namespace,
// so it is baked into all bytecode at construction. The signer attests (EIP-712) each chain's PoolManager / treasury / router
// / NFT / descriptor / hook-codehash entries via `ChainConfig.write_config_as`. Decoupled from the operational treasury so
// each role can rotate independently.
address constant CONFIG_SIGNER                         =  0xE4973e186163aAaa7970272356eaB773d23E6916;
bytes32 constant POOL_MANAGER_KEY                      =  bytes32("uniswap_v4/pool_manager");
bytes32 constant INITIAL_TREASURY_KEY                  =  bytes32("safeswap/initial_treasury");
bytes32 constant SAFESWAP_ROUTER_KEY                   =  bytes32("safeswap/router");
bytes32 constant SAFESWAP_NFT_KEY                      =  bytes32("safeswap/nft");
bytes32 constant SAFESWAP_HOOK_CODEHASH_KEY            =  bytes32("safeswap/hook_codehash");
bytes32 constant SAFESWAP_POSITION_DESCRIPTOR_KEY      =  bytes32("safeswap/position_descriptor");
bytes32 constant SAFESWAP_SIGNING_DESCRIPTOR_KEY       =  bytes32("safeswap/signing_descriptor");
bytes32 constant NATIVE_TOKEN_SYMBOL_KEY               =  bytes32("safeswap/native_token_symbol");
bytes32 constant NATIVE_TOKEN_DECIMALS_KEY             =  bytes32("safeswap/native_token_decimals");


// ━━━━  SAFESWAP ECONOMICS  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

uint256 constant SWAP_STAKE_PERCENTAGE              =   1;

// *NOTE*  -  Applied to the TOTAL value across both legs of the bond, normalized to token0 at slot0. Posted in token0 only.
//            Example: 100 USDC + 100 USDT in a 1:1 pool is total value 200 → 1% = 2 USDC stake (assuming USDC is token0).
uint256 constant LIQUIDITY_STAKE_PERCENTAGE         =   1;

uint256 constant PROTOCOL_FEE_DIVISOR               =   10_000_000; // E.g. 0.3% pool: LPs get full 0.3%, SafeSwap takes 0.03% from output.
uint256 constant MIN_PROTOCOL_FEE_RATE              =   1000;       // 0.01% floor when pool LP fee < 0.10%.


// ━━━━  LP REPRICING REBATE  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
//
// When a swap moves the pool price, the pool charges an additional LP fee equal to a share of the repricing SURPLUS the swap
// extracts, and pays it to the LPs the swap crossed. It is a native Uniswap V4 dynamic fee that accrues per swap step, so it
// compensates LPs in proportion to the volume they served across the move. The hook estimates the surplus before the swap
// (via SwapSimulator) and returns an override fee:
//
//     swap fee (pips)  = base LP fee + repricing fee
//     repricing fee    = capture% × surplus, expressed as a flat rate over the input:
//                        repricing_pips = capture% × surplus / amount_in × 1e6
//     surplus          = (output valued at the post-swap price) − input paid   (input-token units, ≥ 0)
//
// capture% (the hook address's "C" digit, 0..90) is the share of SURPLUS paid to LPs — NOT a rate on price displacement.
// Charging a rate on displacement over-captures by ~2× (a rate hits the whole input; the surplus is only the price-impact
// triangle). See DYNAMIC_FEE_REBATE_PLAN.md / LVR_DETERRENCE.md §4.

uint256 constant BPS_DENOMINATOR            =   10_000;
uint256 constant PERCENT_DENOMINATOR        =   100;        // capture is a percent, so divide by 100.
uint256 constant PIPS_PER_BPS               =   100;        // Uniswap V4 fee units: 1_000_000 = 100%, so 1 bps = 100 pips.
uint256 constant PIPS_PER_PERCENT           =   10_000;     // 1_000_000 pips / 100 percent: converts capture% × (surplus/in) → pips.


// *NOTE*  -  The hook address encoding (base fee + capture markers, shifts, permission bits) and its decoder live in the
//            hook-specific `HookAddress` library (contracts/Hook/HookAddress.sol), not here.


// ━━━━  BONDROUTE EXECUTION POLICY  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

uint256 constant MIN_BOND_EXECUTION_DELAY_IN_BLOCKS   =   3;            // 3-block head-start against reorg and frontrunning bots.
uint256 constant MIN_BOND_EXECUTION_DELAY_IN_SECONDS  =   2 seconds;    // Relevant on chains where 3 blocks pass faster than mempool propagation.
uint256 constant MAX_BOND_EXECUTION_DELAY_IN_SECONDS  =   1 hours;      // Caps opportunistic execution.


// ━━━━  STRINGS  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

string constant SAFESWAP_PROTOCOL_NAME                              =  "SafeSwap";
string constant SAFESWAP_PROTOCOL_DESCRIPTION                       =  "MEV-protected pools. Repricing revenue for LPs.";

string constant SAFESWAP_POSITIONS_NAME                             =  "SafeSwap Positions";
string constant SAFESWAP_POSITIONS_SYMBOL                           =  "SSLP";
string constant SAFESWAP_POSITIONS_DESCRIPTION                      =  "LP positions earning repricing revenue in MEV-protected Uniswap V4 pools";

string constant ADD_LIQUIDITY_REQUIRES_TWO_FUNDINGS                 =  "Add liquidity requires exactly 2 fundings";
string constant REMOVE_LIQUIDITY_REQUIRES_NO_FUNDINGS               =  "Remove liquidity requires 0 fundings";
string constant MODIFY_LIQUIDITY_CREATE_REQUIRES_TWO_FUNDINGS       =  "Modify liquidity create or increase requires exactly 2 fundings";
string constant MODIFY_LIQUIDITY_REMOVE_REQUIRES_NO_FUNDINGS        =  "Modify liquidity remove or collect requires 0 fundings";
string constant DONATE_REQUIRES_TWO_FUNDINGS                        =  "Donate requires exactly 2 fundings";
string constant TOKENS_MUST_BE_DIFFERENT                            =  "Tokens must be different";

contracts/Common/HookAddress.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;


/**
 * @title HookAddress
 * @notice Encoding and decoding of a SafeSwap config-hook address. Every SafeSwap pool's hook is a tiny delegatecall clone
 *         of one implementation whose CREATE2 address carries the pool economics as readable binary-coded decimal:
 *
 *             0x F d2 d1 d0 C r 0 ........................ PPPP
 *                │ └──┬───┘ │ └┬┘                         └─ low 14 bits: Uniswap V4 hook permission bitmap
 *                │    │     │  └─ capture percent digits → 10·r + 0       (0..90, forced 10% steps)
 *                │    │     └──── capture marker (0xC)
 *                │    └────────── 3 base-fee digits      → base fee bps = 100·d2 + 10·d1 + d0   (0..999 → 0.00%..9.99%)
 *                └─────────────── fee marker (0xF), also marks the address as a SafeSwap config hook
 *
 *         Example: 0xF030C50… → base fee 0.3%, capture 50%. The explicit trailing zero makes the percentage readable while
 *         preserving 10%-quantized profiles: addresses such as 0xF030C55… are invalid. The markers 0xF and 0xC are both
 *         greater than 9, so they can never be confused with a 0..9 data digit.
 */
library HookAddress {

    error InvalidHookConfig( address hook );

    uint8   internal constant FEE_MARKER         =   0xF;   // Leading nibble: "Fee" — base-fee digits follow; marks a SafeSwap hook.
    uint8   internal constant CAPTURE_MARKER     =   0xC;   // Separator nibble: "Capture" — two percentage digits follow.
    uint8   internal constant MAX_DECIMAL_DIGIT  =   9;
    uint160 internal constant NIBBLE_MASK        =   0xF;

    uint256 internal constant FEE_MARKER_SHIFT      =   156;
    uint256 internal constant BASE_FEE_D2_SHIFT     =   152;
    uint256 internal constant BASE_FEE_D1_SHIFT     =   148;
    uint256 internal constant BASE_FEE_D0_SHIFT     =   144;
    uint256 internal constant CAPTURE_MARKER_SHIFT  =   140;
    uint256 internal constant REBATE_TENS_SHIFT     =   136;
    uint256 internal constant REBATE_ONES_SHIFT     =   132;

    uint160 internal constant PERMISSIONS_MASK      =   0x3FFF;     // (1 << 14) - 1, matches Hooks.ALL_HOOK_MASK.

    // beforeInitialize | beforeAddLiquidity | beforeRemoveLiquidity | beforeSwap
    //   = (1<<13) | (1<<11) | (1<<9) | (1<<7)
    // (beforeDonate is intentionally NOT required: SafeSwap exposes no bonded donate, and a pool accepting permissionless
    //  donations to its in-range LPs is harmless — it cannot move price or extract value.)
    uint160 internal constant REQUIRED_PERMISSIONS  =   0x2A80;

    /**
     * @notice Decode the base fee (in basis points) and the LP capture share (in percent) from a config-hook address.
     * @dev Reverts if the address does not carry the `0xF` fee marker and `0xC` capture marker, if any value nibble is not
     *      decimal, or if the capture ones digit is not zero.
     */
    function decode( address hook ) internal pure returns ( uint16 base_fee_bps, uint8 rebate_percent )
    {
        uint160 bits  =  uint160(hook);

        uint8 fee_marker      =  uint8( (bits >> FEE_MARKER_SHIFT)     & NIBBLE_MASK );
        uint8 capture_marker  =  uint8( (bits >> CAPTURE_MARKER_SHIFT) & NIBBLE_MASK );
        if(  fee_marker != FEE_MARKER  ||  capture_marker != CAPTURE_MARKER  )  revert InvalidHookConfig( hook );

        uint8 base_fee_hundreds  =  uint8( (bits >> BASE_FEE_D2_SHIFT) & NIBBLE_MASK );
        uint8 base_fee_tens      =  uint8( (bits >> BASE_FEE_D1_SHIFT) & NIBBLE_MASK );
        uint8 base_fee_ones      =  uint8( (bits >> BASE_FEE_D0_SHIFT) & NIBBLE_MASK );
        uint8 rebate_tens_digit  =  uint8( (bits >> REBATE_TENS_SHIFT) & NIBBLE_MASK );
        uint8 rebate_ones_digit  =  uint8( (bits >> REBATE_ONES_SHIFT) & NIBBLE_MASK );

        bool any_digit_invalid  =  base_fee_hundreds > MAX_DECIMAL_DIGIT
                                   ||  base_fee_tens > MAX_DECIMAL_DIGIT
                                   ||  base_fee_ones > MAX_DECIMAL_DIGIT
                                   ||  rebate_tens_digit > MAX_DECIMAL_DIGIT
                                   ||  rebate_ones_digit > MAX_DECIMAL_DIGIT;
        if(  any_digit_invalid  ||  rebate_ones_digit != 0  )  revert InvalidHookConfig( hook );

        base_fee_bps    =  uint16(base_fee_hundreds) * 100  +  uint16(base_fee_tens) * 10  +  uint16(base_fee_ones);
        rebate_percent  =  rebate_tens_digit * 10;
    }

    /**
     * @notice Whether `hook`'s low 14 bits carry exactly the Uniswap V4 permission bitmap a SafeSwap hook requires.
     */
    function has_required_permissions( address hook ) internal pure returns ( bool )
    {
        return ( uint160(hook) & PERMISSIONS_MASK ) == REQUIRED_PERMISSIONS;
    }
}

contracts/Common/SafeSwapCommon.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import "@BondRouteProtected/BondRouteProtected.sol";
import "@SafeSwapCommon/Definitions.sol";
import "@SafeSwapCommon/Types.sol";
import { IPoolManager } from "@UniswapV4Core/interfaces/IPoolManager.sol";
import { IHooks } from "@UniswapV4Core/interfaces/IHooks.sol";
import { PoolKey } from "@UniswapV4Core/types/PoolKey.sol";
import { Currency } from "@UniswapV4Core/types/Currency.sol";
import { FullMath } from "@UniswapV4Core/libraries/FullMath.sol";
import { FixedPoint96 } from "@UniswapV4Core/libraries/FixedPoint96.sol";
import { LPFeeLibrary } from "@UniswapV4Core/libraries/LPFeeLibrary.sol";


// ━━━━  ERRORS  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

error SlippageExceeded( uint256 amount_received, uint256 minimum_required );
error MaximumInputExceeded( uint256 required_input, uint256 maximum_required );
error OneSidedDepositMismatch( address expected_token, uint256 minimum_required );
error RepricingFeeExceedsV4Limit( uint256 total_fee_pips, uint256 maximum_fee_pips );

// The swap funding the bond carries must match the input the user signed in the receipt (`Pay`). The signed input is the
// display source of truth; a relayer cannot fund a different token or amount than the one the user saw and signed.
error SignedSwapInputMismatch( address signed_token, uint256 signed_amount, address funded_token, uint256 funded_amount );


/**
 * @title SafeSwapCommon
 * @notice Shared utilities for SafeSwap action libraries.
 * @dev Constants, pool key building, stake calculation, protocol fee math, repricing-fee math, and settlement logic.
 */
library SafeSwapCommon {
    using FundingsLib for BondContext;

    // EIP-712 type hashes shared across action libs.
    bytes32 constant POOL_INFO_TYPEHASH     =  keccak256( "PoolInfo(uint16 base_fee_bps,uint8 rebate_percent,int24 tick_spacing)" );
    bytes32 constant TOKEN_AMOUNT_TYPEHASH  =  keccak256( "TokenAmount(address token,uint256 amount)" );


    // ━━━━  EIP-712 HELPERS  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    // EIP-712 encodes each atomic member into a full 32-byte word: uint8 zero-padded, int24 sign-extended. `abi.encode`
    // produces exactly that layout, so we hash it directly rather than hand-rolling assembly for this off-chain signing path.
    function hash_pool_info( PoolInfo memory pool_info ) internal pure returns ( bytes32 result )
    {
        result  =  keccak256( abi.encode(
            POOL_INFO_TYPEHASH,
            pool_info.base_fee_bps,
            pool_info.rebate_percent,
            pool_info.tick_spacing
        ));
    }

    function hash_token_amount( TokenAmount memory token_amount ) internal pure returns ( bytes32 result )
    {
        bytes32 typehash  =  TOKEN_AMOUNT_TYPEHASH;

        assembly ("memory-safe")
        {
            let saved_free_memory_pointer  :=  mload( 0x40 )

            // Lay out  typehash || token || amount  across the 96 bytes spanning the scratch
            // space (0x00-0x3f) and the free-memory-pointer slot (0x40-0x5f). This leaves no
            // garbage above the free memory pointer.
            // The token field is a memory-stored address, already right-aligned in its 32-byte slot.
            mstore( 0x00, typehash )
            mstore( 0x20, mload( token_amount ) )                  // token
            mstore( 0x40, mload( add( token_amount, 0x20 ) ) )     // amount

            result  :=  keccak256( 0x00, 0x60 )

            mstore( 0x40, saved_free_memory_pointer )    // *SECURITY*  -  Restore the free memory pointer we just clobbered.
        }
    }


    // ━━━━  POOL CONFIG HELPERS  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    /**
     * @notice Convert a base LP fee in basis points into Uniswap V4 fee units (pips).
     * @dev 100 v4 pips = 1 bps. E.g. 30 bps (0.3%) → 3000 pips.
     */
    function compute_base_fee_pips( uint16 base_fee_bps ) internal pure returns ( uint24 )
    {
        return uint24(base_fee_bps) * uint24(PIPS_PER_BPS);
    }


    // ━━━━  TOKEN AMOUNT HELPERS  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    /**
     * @notice Sort a two-element TokenAmount pair into Uniswap V4 pool currency order.
     * @dev Reverts with `TOKENS_MUST_BE_DIFFERENT` if both entries reference the same token.
     */
    function sort_token_amount_pair( TokenAmount memory pair_a, TokenAmount memory pair_b )
    internal pure returns ( IERC20 token0, uint256 amount0, IERC20 token1, uint256 amount1 )
    {
        if(  address(pair_a.token) == address(pair_b.token)  )  revert( TOKENS_MUST_BE_DIFFERENT );

        ( token0, amount0, token1, amount1 )  =  address(pair_a.token) < address(pair_b.token)
            ? ( pair_a.token, pair_a.amount, pair_b.token, pair_b.amount )
            : ( pair_b.token, pair_b.amount, pair_a.token, pair_a.amount );
    }


    // ━━━━  POOL KEY BUILDER  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    function build_pool_key( IERC20 token_in, IERC20 token_out, uint24 fee, int24 tick_spacing, address hook_address )
    internal pure returns ( PoolKey memory )
    {
        ( Currency currency0, Currency currency1 )  =  address(token_in) < address(token_out)
            ? ( Currency.wrap(address(token_in)), Currency.wrap(address(token_out)) )
            : ( Currency.wrap(address(token_out)), Currency.wrap(address(token_in)) );

        return PoolKey({
            currency0: currency0,
            currency1: currency1,
            fee: fee,
            tickSpacing: tick_spacing,
            hooks: IHooks(hook_address)
        });
    }


    // ━━━━  STAKE CALCULATION  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    function calculate_swap_stake( TokenAmount memory funding ) internal pure returns ( TokenAmount memory )
    {
        uint256 stake_amount  =  funding.amount * SWAP_STAKE_PERCENTAGE / 100;

        // *SECURITY*  -  Bump dust to 1 wei. For 0-decimal / low-decimal tokens where 1 wei = 1 unit = real value
        //                (gaming ERC20s, fractional RWAs), this turns a free speculative bond into a meaningful stake.
        if(  stake_amount == 0  )  stake_amount  =  1;

        return TokenAmount({ token: funding.token, amount: stake_amount });
    }

    // *SECURITY*  -  Stake must reflect the total committed value across BOTH sides of a liquidity bond. Measuring
    //                only one side opens a dust attack: (amount0 = 1 wei, amount1 = 1e18) would yield zero stake while
    //                committing real value. By default we normalize amount1 into token0 units at the pool's current
    //                price (slot0). If the user signals token1 as the preferred stake token, we normalize amount0 into
    //                token1 instead. Any other preference is ignored and falls back to token0.
    //                Caveat: on very thin pools an attacker can shift slot0 cheaply, so the per-bond stake reflects
    //                a manipulated price. This is bounded by SafeSwap's own 1% swap stake on the manipulation swap.
    function calculate_normalized_liquidity_stake(
        uint160 sqrtPriceX96,
        IERC20 token0,
        IERC20 token1,
        uint256 amount0,
        uint256 amount1,
        IERC20 preferred_stake_token
    )
    internal pure returns ( TokenAmount memory )
    {
        bool is_token1_preferred  =  address(preferred_stake_token) == address(token1);
        IERC20 stake_token        =  is_token1_preferred  ?  token1  :  token0;
        uint256 normalized_total  =  is_token1_preferred
            ?  amount1 + _convert_token0_to_token1_units( sqrtPriceX96, amount0 )
            :  amount0 + _convert_token1_to_token0_units( sqrtPriceX96, amount1 );

        uint256 stake_amount  =  normalized_total * LIQUIDITY_STAKE_PERCENTAGE / 100;

        // *SECURITY*  -  Bump dust to 1 wei. For 0-decimal / low-decimal tokens where 1 wei = 1 unit = real value
        //                (gaming ERC20s, fractional RWAs), this turns a free speculative bond into a meaningful stake.
        if(  stake_amount == 0  )  stake_amount  =  1;

        return TokenAmount({ token: stake_token, amount: stake_amount });
    }

    function _convert_token1_to_token0_units( uint160 sqrtPriceX96, uint256 amount1 ) private pure returns ( uint256 amount1_in_token0_units )
    {
        if(  amount1 == 0  )  return 0;

        // Price (token1 per token0)  =  sqrtPriceX96^2 / 2^192.
        // So amount1 in token0 units =  amount1 * 2^192 / sqrtPriceX96^2.
        // Performed as two mulDiv steps to avoid uint256 overflow on sqrtPriceX96^2 at high prices.
        uint256 intermediate      =  FullMath.mulDiv( amount1, FixedPoint96.Q96, sqrtPriceX96 );
        amount1_in_token0_units   =  FullMath.mulDiv( intermediate, FixedPoint96.Q96, sqrtPriceX96 );
    }

    function _convert_token0_to_token1_units( uint160 sqrtPriceX96, uint256 amount0 ) private pure returns ( uint256 amount0_in_token1_units )
    {
        if(  amount0 == 0  )  return 0;

        // Price (token1 per token0)  =  sqrtPriceX96^2 / 2^192.
        // So amount0 in token1 units =  amount0 * sqrtPriceX96^2 / 2^192.
        // Performed as two mulDiv steps to avoid uint256 overflow on sqrtPriceX96^2 at high prices.
        uint256 intermediate      =  FullMath.mulDiv( amount0, sqrtPriceX96, FixedPoint96.Q96 );
        amount0_in_token1_units   =  FullMath.mulDiv( intermediate, sqrtPriceX96, FixedPoint96.Q96 );
    }


    // ━━━━  PROTOCOL FEE CALCULATION  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    function calculate_protocol_fee( uint256 amount_out, uint24 pool_fee ) internal pure returns ( uint256 protocol_fee, uint256 user_amount )
    {
        uint256 effective_fee_rate  =  pool_fee < MIN_PROTOCOL_FEE_RATE  ?  MIN_PROTOCOL_FEE_RATE  :  pool_fee;
        protocol_fee                =  amount_out * effective_fee_rate / PROTOCOL_FEE_DIVISOR;
        user_amount                 =  amount_out - protocol_fee;
    }


    // ━━━━  REPRICING FEE  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    /**
     * @notice Compute the total swap fee (in Uniswap V4 pips) from a swap's estimated repricing surplus.
     * @param amount_in Input the swap pays (estimated at the base fee).
     * @param amount_out Output the swap receives (estimated at the base fee).
     * @param sqrt_price_after_x96 Estimated post-swap sqrt price — the terminal price the output is valued at.
     * @param zero_for_one Swap direction (token0 → token1 when true).
     * @param capture_percent LP capture share in percent (0..90): the share of SURPLUS paid to LPs.
     * @param base_fee_pips Base LP fee in v4 pips.
     * @return swap_fee_pips Base fee plus the repricing fee, in v4 pips, to be returned as the dynamic-fee override.
     *
     * @dev `surplus = (output valued at the post-swap price) − input`, in input-token units (clamped at 0). The repricing
     *      fee is `capture% × surplus`, expressed as a flat rate over the input: `capture% × surplus / amount_in × 1e6`.
     *      Direction-neutral. If enforcing the configured capture would require a 100%+ V4 fee, the swap reverts instead of
     *      silently under-capturing LPs. This is NOT `capture% × displacement`: that over-captures by ~2×.
     */
    function compute_repricing_fee_pips(
        uint256 amount_in,
        uint256 amount_out,
        uint160 sqrt_price_after_x96,
        bool zero_for_one,
        uint8 capture_percent,
        uint24 base_fee_pips
    ) internal pure returns ( uint24 swap_fee_pips )
    {
        uint256 repricing_pips  =  _repricing_fee_pips( amount_in, amount_out, sqrt_price_after_x96, zero_for_one, capture_percent );
        uint256 total_pips  =  uint256(base_fee_pips) + repricing_pips;

        if(  total_pips >= LPFeeLibrary.MAX_LP_FEE  )
        {
            revert RepricingFeeExceedsV4Limit({ total_fee_pips: total_pips, maximum_fee_pips: LPFeeLibrary.MAX_LP_FEE - 1 });
        }

        swap_fee_pips  =  uint24(total_pips);
    }

    /**
     * @notice Split the Uniswap V4 swap-amount convention into `(amount_in, amount_out)` given the simulator's counterpart.
     * @dev `amount_specified < 0` is exact-input (amount_in = |specified|, amount_out = counterpart); `> 0` is exact-output.
     */
    function compute_swap_amounts( int256 amount_specified, uint256 counterpart ) internal pure returns ( uint256 amount_in, uint256 amount_out )
    {
        if(  amount_specified < 0  )
        {
            amount_in   =  uint256(-amount_specified);
            amount_out  =  counterpart;
        }
        else
        {
            amount_out  =  uint256(amount_specified);
            amount_in   =  counterpart;
        }
    }

    // Repricing fee in v4 pips = `capture% × surplus / amount_in × 1e6`, where surplus = output valued at the post-swap price
    // minus the input, in input-token units (0 if not positive). FullMath keeps the valuation and pip conversion exact.
    function _repricing_fee_pips( uint256 amount_in, uint256 amount_out, uint160 sqrt_price_after_x96, bool zero_for_one, uint8 capture_percent )
    private pure returns ( uint256 )
    {
        if(  amount_in == 0  ||  capture_percent == 0  )  return 0;

        uint256 output_in_input_units  =  _value_output_in_input( amount_out, sqrt_price_after_x96, zero_for_one );
        if(  output_in_input_units <= amount_in  )  return 0;

        uint256 surplus  =  output_in_input_units - amount_in;

        // capture% × surplus / amount_in × 1e6  =  surplus × (capture% × 1e6/100) / amount_in.
        return FullMath.mulDiv( surplus, uint256(capture_percent) * PIPS_PER_PERCENT, amount_in );
    }

    // Value `amount_out` (the output token) in input-token units at the post-swap price P = (sqrtP / 2^96)^2 (token1/token0):
    //   zeroForOne (out = token1): value in token0 = amount_out / P = amount_out · 2^192 / sqrtP^2
    //   oneForZero (out = token0): value in token1 = amount_out · P = amount_out · sqrtP^2 / 2^192
    function _value_output_in_input( uint256 amount_out, uint160 sqrt_price_after_x96, bool zero_for_one )
    private pure returns ( uint256 )
    {
        uint256 sqrt_price  =  uint256(sqrt_price_after_x96);

        if(  zero_for_one  )
        {
            uint256 term  =  FullMath.mulDiv( amount_out, FixedPoint96.Q96, sqrt_price );
            return          FullMath.mulDiv( term, FixedPoint96.Q96, sqrt_price );
        }

        uint256 scaled  =  FullMath.mulDiv( amount_out, sqrt_price, FixedPoint96.Q96 );
        return              FullMath.mulDiv( scaled, sqrt_price, FixedPoint96.Q96 );
    }


    // ━━━━  SETTLEMENT  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    // *NATIVE*  -  V4 PoolManager has no receive(); native ETH cannot be transferred to it separately and then settled.
    //              It must arrive bundled with `settle{value:}()`. So for native we pull ETH to the router (which has
    //              receive()) and forward via msg.value on settle. For ERC20 we keep the direct user→PM path.
    function settle_input( IPoolManager pool_manager, BondContext memory context, IERC20 token, uint256 amount ) internal
    {
        if(  amount == 0  )  return;

        pool_manager.sync( Currency.wrap( address(token) ) );

        if(  address(token) == address(0)  )
        {
            context.pull( token, amount );
            pool_manager.settle{ value: amount }( );
        }
        else
        {
            context.send( token, amount, address(pool_manager) );
            pool_manager.settle( );
        }
    }

    /**
     * @notice Settle the swap input, send the user their net output, and take the protocol fee.
     * @param fee_recipient SafeSwap router address that receives the protocol fee (held for the treasury).
     */
    function settle_and_take(
        IPoolManager pool_manager,
        BondContext memory context,
        IERC20 token_in,
        IERC20 token_out,
        uint256 amount_in,
        uint256 user_output,
        uint256 protocol_fee,
        address fee_recipient
    ) internal
    {
        Currency currency_out  =  Currency.wrap( address(token_out) );

        settle_input( pool_manager, context, token_in, amount_in );

        pool_manager.take( currency_out, context.user, user_output );
        pool_manager.take( currency_out, fee_recipient, protocol_fee );
    }
}

contracts/Common/SwapSimulator.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import { IPoolManager } from "@UniswapV4Core/interfaces/IPoolManager.sol";
import { PoolKey } from "@UniswapV4Core/types/PoolKey.sol";
import { PoolId, PoolIdLibrary } from "@UniswapV4Core/types/PoolId.sol";
import { TickMath } from "@UniswapV4Core/libraries/TickMath.sol";
import { SwapMath } from "@UniswapV4Core/libraries/SwapMath.sol";
import { TickBitmap } from "@UniswapV4Core/libraries/TickBitmap.sol";
import { BitMath } from "@UniswapV4Core/libraries/BitMath.sol";
import { LiquidityMath } from "@UniswapV4Core/libraries/LiquidityMath.sol";


/**
 * @title SwapSimulator
 * @notice Read-only forward simulation of a Uniswap V4 swap's price path. Given live pool state and a swap request, it
 *         returns the tick the swap would land on — the input the LP repricing rebate needs to price movement BEFORE the
 *         swap executes (a v4 dynamic LP fee must be chosen in `beforeSwap`, before the realized movement is known).
 *
 * @dev Faithful port of `Pool.swap`'s loop (both swap directions, exact-input and exact-output, multi-word), so the
 *      returned tick matches the real swap. Simulate with the pool's base LP fee; the fee-vs-movement feedback is
 *      second-order. The slots read here are exactly the slots the real swap reads, so running this immediately before
 *      the swap warms them — the cold storage cost is paid by the swap regardless.
 *
 *      Performance: pool state is read through raw `extsload` staticcalls assembled inline (no Solidity ABI encode/decode
 *      of return arrays), storage slots are derived in assembly using only the two EVM scratch words (0x00, 0x20) so the
 *      free-memory pointer is never disturbed, and the tick bitmap word is read once per 256-tick word rather than once
 *      per crossing. The AMM arithmetic itself reuses Uniswap's already-optimized `SwapMath` / `TickMath` libraries.
 */
library SwapSimulator {
    using PoolIdLibrary for PoolKey;

    // Storage layout of Uniswap V4 `PoolManager`: `mapping(PoolId => Pool.State) pools` at slot 6, and within Pool.State
    // the liquidity, ticks mapping, and tickBitmap mapping at these offsets. Mirrors `StateLibrary`.
    uint256 constant POOLS_SLOT          =  6;
    uint256 constant LIQUIDITY_OFFSET    =  3;
    uint256 constant TICKS_OFFSET        =  4;
    uint256 constant TICK_BITMAP_OFFSET  =  5;

    // `extsload(bytes32)` selector — single-slot raw read.
    uint256 constant EXTSLOAD_SELECTOR   =  0x1e2eaeaf;

    /// @notice Working state threaded through the walk so the bitmap word is fetched once per word, not once per tick.
    struct WordCache {
        bytes32 bitmap_mapping_slot;
        int16 word_pos;
        uint256 word;
        bool loaded;
    }

    /// @notice Immutable inputs of the price-path walk, bundled so the per-step helper stays shallow on the stack (keeping
    ///         the loop compilable under both the IR and the legacy codegen pipelines).
    struct SimEnv {
        IPoolManager manager;
        bytes32 ticks_mapping;
        int24 tick_spacing;
        bool zero_for_one;
        int256 amount_specified;
        uint24 fee_pips;
        uint160 price_limit;
    }

    /// @notice Mutable state advanced by each walk step.
    struct SimState {
        uint160 sqrt_price_x96;
        int24 tick;
        uint128 liquidity;
        int256 remaining;
        uint256 amount_calculated;
    }

    /**
     * @notice Estimate where a swap would move the pool price.
     * @param amount_specified Negative for exact-input, positive for exact-output (Uniswap V4 convention).
     * @param fee_pips Swap fee in pips to simulate with (the pool's base LP fee).
     * @return tick_before Pool tick before the swap.
     * @return tick_after Estimated pool tick after the swap.
     * @return sqrt_price_after_x96 Estimated post-swap sqrt price.
     * @return amount_calculated Counterpart amount at `fee_pips`: total output for exact-input, total input for exact-output.
     */
    function simulate( IPoolManager manager, PoolKey memory key, bool zero_for_one, int256 amount_specified, uint24 fee_pips )
    internal view returns ( int24 tick_before, int24 tick_after, uint160 sqrt_price_after_x96, uint256 amount_calculated )
    {
        bytes32 state_slot     =  _pool_state_slot( key.toId( ) );
        bytes32 ticks_mapping  =  bytes32( uint256(state_slot) + TICKS_OFFSET );

        bytes32 slot0  =  _extsload( manager, state_slot );
        uint160 sqrt_price_x96  =  uint160(uint256(slot0));   // low 160 bits of slot0 hold sqrtPriceX96 (truncating cast).
        int24 tick;
        assembly ("memory-safe")
        {
            tick  :=  signextend( 2, shr(160, slot0) )         // bits 160-183 hold the signed current tick.
        }

        tick_before  =  tick;

        uint128 liquidity  =  uint128(uint256( _extsload( manager, bytes32( uint256(state_slot) + LIQUIDITY_OFFSET ) ) ));

        WordCache memory cache;
        cache.bitmap_mapping_slot  =  bytes32( uint256(state_slot) + TICK_BITMAP_OFFSET );

        SimEnv memory env  =  SimEnv({
            manager:          manager,
            ticks_mapping:    ticks_mapping,
            tick_spacing:     key.tickSpacing,
            zero_for_one:     zero_for_one,
            amount_specified: amount_specified,
            fee_pips:         fee_pips,
            price_limit:      zero_for_one  ?  TickMath.MIN_SQRT_PRICE + 1  :  TickMath.MAX_SQRT_PRICE - 1
        });

        SimState memory state  =  SimState({ sqrt_price_x96: sqrt_price_x96, tick: tick, liquidity: liquidity, remaining: amount_specified, amount_calculated: 0 });

        while(  state.remaining != 0  &&  state.sqrt_price_x96 != env.price_limit  )
        {
            _walk_step( env, cache, state );
        }

        tick_after            =  state.tick;
        sqrt_price_after_x96  =  state.sqrt_price_x96;
        amount_calculated     =  state.amount_calculated;
    }

    /// @notice Advance one price-path step (one tick crossing or one within-word move), mirroring a single iteration of
    ///         `Pool.swap`'s loop. Mutates `cache` (bitmap word reuse) and `state` (price / tick / liquidity / totals).
    function _walk_step( SimEnv memory env, WordCache memory cache, SimState memory state ) private view
    {
        unchecked
        {
            uint160 start_price_x96  =  state.sqrt_price_x96;

            ( int24 tick_next, bool initialized )  =  _next_initialized_tick( env.manager, cache, state.tick, env.tick_spacing, env.zero_for_one );

            if(  tick_next <= TickMath.MIN_TICK  )  tick_next  =  TickMath.MIN_TICK;
            if(  tick_next >= TickMath.MAX_TICK  )  tick_next  =  TickMath.MAX_TICK;

            uint160 sqrt_price_next_x96  =  TickMath.getSqrtPriceAtTick( tick_next );

            uint256 amount_in;
            uint256 amount_out;
            uint256 fee_amount;
            ( state.sqrt_price_x96, amount_in, amount_out, fee_amount )  =  SwapMath.computeSwapStep(
                state.sqrt_price_x96,
                SwapMath.getSqrtPriceTarget( env.zero_for_one, sqrt_price_next_x96, env.price_limit ),
                state.liquidity,
                state.remaining,
                env.fee_pips
            );

            if(  env.amount_specified > 0  )
            {
                state.remaining          -=  int256(amount_out);
                state.amount_calculated  +=  amount_in + fee_amount;     // exact-output: accumulate the required input.
            }
            else
            {
                state.remaining          +=  int256(amount_in + fee_amount);
                state.amount_calculated  +=  amount_out;                 // exact-input: accumulate the produced output.
            }

            if(  state.sqrt_price_x96 == sqrt_price_next_x96  )
            {
                if(  initialized  )
                {
                    int128 liquidity_net  =  _liquidity_net( env.manager, env.ticks_mapping, tick_next );
                    if(  env.zero_for_one  )  liquidity_net  =  -liquidity_net;

                    state.liquidity  =  LiquidityMath.addDelta( state.liquidity, liquidity_net );
                }

                state.tick  =  env.zero_for_one  ?  tick_next - 1  :  tick_next;
            }
            else if(  state.sqrt_price_x96 != start_price_x96  )
            {
                state.tick  =  TickMath.getTickAtSqrtPrice( state.sqrt_price_x96 );
            }
        }
    }


    // ━━━━  TICK BITMAP WALK  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    // Same result as `TickBitmap.nextInitializedTickWithinOneWord`, but reads the bitmap word through the cache so repeated
    // searches inside one 256-tick word reuse a single storage read.
    function _next_initialized_tick( IPoolManager manager, WordCache memory cache, int24 tick, int24 tick_spacing, bool lte )
    private view returns ( int24 next, bool initialized )
    {
        unchecked
        {
            int24 compressed  =  TickBitmap.compress( tick, tick_spacing );

            if(  lte  )
            {
                ( int16 word_pos, uint8 bit_pos )  =  TickBitmap.position( compressed );
                uint256 word    =  _word( manager, cache, word_pos );
                uint256 masked  =  word & ( type(uint256).max >> ( uint256(type(uint8).max) - bit_pos ) );

                initialized  =  masked != 0;
                next  =  initialized
                    ? ( compressed - int24(uint24(bit_pos - BitMath.mostSignificantBit( masked ))) ) * tick_spacing
                    : ( compressed - int24(uint24(bit_pos)) ) * tick_spacing;
            }
            else
            {
                int24 next_compressed  =  compressed + 1;
                ( int16 word_pos, uint8 bit_pos )  =  TickBitmap.position( next_compressed );
                uint256 word    =  _word( manager, cache, word_pos );
                uint256 masked  =  word & ~( ( uint256(1) << bit_pos ) - 1 );

                initialized  =  masked != 0;
                next  =  initialized
                    ? ( next_compressed + int24(uint24(BitMath.leastSignificantBit( masked ) - bit_pos)) ) * tick_spacing
                    : ( next_compressed + int24(uint24(type(uint8).max - bit_pos)) ) * tick_spacing;
            }
        }
    }

    function _word( IPoolManager manager, WordCache memory cache, int16 word_pos ) private view returns ( uint256 )
    {
        if(  cache.loaded  &&  cache.word_pos == word_pos  )  return cache.word;

        uint256 word  =  uint256( _extsload( manager, _bitmap_word_slot( cache.bitmap_mapping_slot, word_pos ) ) );

        cache.word_pos  =  word_pos;
        cache.word      =  word;
        cache.loaded    =  true;

        return word;
    }

    function _liquidity_net( IPoolManager manager, bytes32 ticks_mapping_slot, int24 tick ) private view returns ( int128 liquidity_net )
    {
        // TickInfo packs `liquidityNet` in the high 128 bits of its first word; `liquidityGross` occupies the low 128 bits.
        bytes32 first_word  =  _extsload( manager, _tick_info_slot( ticks_mapping_slot, tick ) );
        assembly ("memory-safe") { liquidity_net := sar( 128, first_word ) }
    }


    // ━━━━  STORAGE SLOT DERIVATION (assembly, scratch-only)  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    function _pool_state_slot( PoolId pool_id ) private pure returns ( bytes32 state_slot )
    {
        // pools[poolId] => keccak256( poolId . POOLS_SLOT ). Uses only the two EVM scratch words.
        assembly ("memory-safe")
        {
            mstore( 0x00, pool_id )
            mstore( 0x20, POOLS_SLOT )
            state_slot  :=  keccak256( 0x00, 0x40 )
        }
    }

    function _bitmap_word_slot( bytes32 bitmap_mapping_slot, int16 word_pos ) private pure returns ( bytes32 slot )
    {
        // tickBitmap[word_pos] => keccak256( int256(word_pos) . bitmap_mapping_slot ).
        assembly ("memory-safe")
        {
            mstore( 0x00, word_pos )
            mstore( 0x20, bitmap_mapping_slot )
            slot  :=  keccak256( 0x00, 0x40 )
        }
    }

    function _tick_info_slot( bytes32 ticks_mapping_slot, int24 tick ) private pure returns ( bytes32 slot )
    {
        // ticks[tick] => keccak256( int256(tick) . ticks_mapping_slot ).
        assembly ("memory-safe")
        {
            mstore( 0x00, tick )
            mstore( 0x20, ticks_mapping_slot )
            slot  :=  keccak256( 0x00, 0x40 )
        }
    }


    // ━━━━  RAW EXTSLOAD (assembly, scratch-only)  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

    // Single-slot `extsload` without Solidity ABI machinery. Calldata `selector(4) . slot(32)` and the 32-byte return both
    // live entirely in the two scratch words (0x00-0x3f); the free-memory pointer at 0x40 is never touched.
    function _extsload( IPoolManager manager, bytes32 slot ) private view returns ( bytes32 value )
    {
        assembly ("memory-safe")
        {
            mstore( 0x00, EXTSLOAD_SELECTOR )     // right-aligned: selector occupies bytes 0x1c-0x1f.
            mstore( 0x20, slot )

            // *SECURITY*  -  A failed staticcall (bad PoolManager) must not be read as a zero slot; bubble the revert.
            if iszero( staticcall( gas(), manager, 0x1c, 0x24, 0x00, 0x20 ) )
            {
                returndatacopy( 0x00, 0x00, returndatasize() )
                revert( 0x00, returndatasize() )
            }

            value  :=  mload( 0x00 )
        }
    }
}

contracts/Common/Types.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.30;

import { IERC20 } from "@BondRouteProtected/BondRouteProtected.sol";


// ━━━━  DATA STRUCTURES  ━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

/**
 * @notice SafeSwap pool configuration shared by all SafeSwap actions.
 * @param base_fee_bps Base LP fee in basis points (1 bps = 0.01%), 0..999. Selects the config hook (encoded in its address).
 * @param rebate_percent LP capture share in percent (0..90, in 10% steps). Selects the config hook and the repricing fee share.
 * @param tick_spacing Pool tick spacing.
 */
struct PoolInfo {
    uint16 base_fee_bps;
    uint8 rebate_percent;
    int24 tick_spacing;
}

/**
 * @notice Immutable metadata for a SafeSwap NFT-backed Uniswap V4 position.
 * @param opened_at Timestamp when the LP NFT was minted.
 * @param hook SafeSwap config hook (clone) that identifies the pool's base fee and capture share.
 * @param token0 Pool currency0.
 * @param token1 Pool currency1.
 * @param base_fee_bps Base LP fee in basis points. Derivable from `hook`, stored for cheap rendering and verification.
 * @param rebate_percent LP capture share in percent. Derivable from `hook`, stored for cheap rendering and verification.
 * @param tick_spacing Pool tick spacing.
 * @param tick_lower Lower tick of the position.
 * @param tick_upper Upper tick of the position.
 */
struct SafeSwapPositionInfo {
    uint40 opened_at;
    address hook;
    IERC20 token0;
    IERC20 token1;
    uint16 base_fee_bps;
    uint8 rebate_percent;
    int24 tick_spacing;
    int24 tick_lower;
    int24 tick_upper;
}

